grid=[[8,1,3,1,7,3],[1,1,7,3,1,1],[8,7,1,3,1,1]]
out=[]
for r in range(11):
    if r in (3,7): out.append([6]*13); continue
    rr=r%4
    row=[]
    for c in range(13):
        if c==6: row.append(6)
        else: row.append(grid[rr][c%7 if c<6 else (c-7)])
    out.append(row)
print(out)

